import {acceptedNames,acceptsName,isNameLanguage,NAME_LANGUAGES} from './name-languages.js';
export const normalize=s=>String(s??'').toLowerCase().replace(/ä/g,'a').replace(/ö/g,'o').replace(/ü/g,'u').replace(/ß/g,'ss').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\p{L}\p{N}]/gu,'');
export function matches(s,q){return q.trim().split(/\s+/).every(t=>[s.de,s.en,s.enGB,s.sci,...s.codes,...s.aliases.de,...(s.germanNames||[]).map(n=>n.name),...s.aliases.en,...NAME_LANGUAGES.flatMap(l=>acceptedNames(s,l.code))].some(v=>normalize(v).includes(normalize(t))||normalize(v).includes(normalize(t.replace(/ae/g,'ä').replace(/oe/g,'ö').replace(/ue/g,'ü')))));}
export function accepts(s,target,value){if(target!=='code')return acceptsName(s,target,value);const answer=normalize(value);return !!answer&&s.codes.some(v=>normalize(v)===answer);}
export function review(old,correct,now=Date.now(),hint=false){let p={attempts:0,correct:0,streak:0,lapses:0,interval:0,...old};p.attempts++;p.correct+=+correct;p.last=now;p.lastWrong=!correct;p.streak=correct&&!hint?p.streak+1:0;p.lapses+=+!correct;p.interval=correct&&!hint?[1,3,7,14,30,60][Math.min(p.streak-1,5)]:0;p.due=now+(p.interval? p.interval*86400000:600000);return p;}
export const mastered=p=>!!p&&p.streak>=3;
export const due=(p,now=Date.now())=>!!p&&p.due<=now;
export function validProgress(x,ids){if(!x||x.app!=='BirdNames DE'||x.version!==1||!x.records||typeof x.records!=='object'||Array.isArray(x.records))throw Error('Keine gültige BirdNames-DE-Sicherung.');let records={};for(const [k,p]of Object.entries(x.records)){let [id,t,...extra]=k.split(':');if(extra.length||!ids.has(id)||!(isNameLanguage(t)||t==='code'))continue;if(!p||typeof p!=='object')throw Error('Ungültiger Lerneintrag.');for(let f of ['attempts','correct','streak','lapses','interval','due','last'])if(typeof p[f]!=='number'||!Number.isFinite(p[f])||p[f]<0)throw Error('Ungültige Lernwerte.');for(let f of ['lessonFirstAttempts','lessonFirstCorrect','lessonRepeatAttempts'])if(p[f]!==undefined&&(!Number.isInteger(p[f])||p[f]<0))throw Error('Ungültige getrennte Antwortzähler.');if((p.lessonFirstCorrect||0)>(p.lessonFirstAttempts||0)||(p.lessonFirstAttempts||0)+(p.lessonRepeatAttempts||0)>p.attempts)throw Error('Widersprüchliche Antwortzähler.');if(p.correct>p.attempts||p.streak>p.correct||typeof p.lastWrong!=='boolean')throw Error('Widersprüchliche Lernwerte.');records[k]={...p};}return records;}
